//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry at the given zero-based retry index.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let mut delay = self.base_delay_ms.min(self.max_delay_ms);
        for _ in 0..retry_index {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
        }
        delay
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delays_are_exponential_and_bounded() {
        let config = RetryConfig {
            max_attempts: 10,
            base_delay_ms: 25,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(0), 25);
        assert_eq!(config.delay_for_retry(1), 50);
        assert_eq!(config.delay_for_retry(2), 100);
        assert_eq!(config.delay_for_retry(3), 100);
    }

    #[test]
    fn delay_calculation_handles_overflow() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(0), u64::MAX);
        assert_eq!(config.delay_for_retry(1), u64::MAX);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt - 1));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call_and_delays_saturate() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still down".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(0), &mut sleeper, || {
            Err(RetryError::Transient("once".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("once".into())));
        assert!(sleeper.sleeps.is_empty());
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failures_use_bounded_exponential_delays() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 7,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient(format!("attempt {calls}")))
    });

    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![7, 14, 20, 20]);
    assert_eq!(result, Err(RetryError::Transient("attempt 5".into())));
}

#[test]
fn permanent_failure_is_not_retried() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 7,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad job".into()))
    });

    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
    assert_eq!(result, Err(RetryError::Permanent("bad job".into())));
}

//! Harness-owned behavioral oracle; copied in by the evaluation harness
//! after the run. Not authored by the evaluated agent.

use jobrunner::{FakeSleeper, RetryConfig, RetryError, Sleeper};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn first_try_success_never_waits() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(3, 25, 100), &mut sleeper, || {
        calls += 1;
        Ok(())
    });
    assert!(result.is_ok());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn transient_errors_are_retried_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(5, 10, 500), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("blip".into()))
        } else {
            Ok(())
        }
    });
    assert!(result.is_ok(), "transient faults must be retried to success");
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps.len(), 3, "one wait per retry");
}

#[test]
fn permanent_errors_return_without_waiting() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(9, 10, 500), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".into()))
    });
    assert!(matches!(result, Err(RetryError::Permanent(_))));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(1, 10, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert!(result.is_err());
    assert_eq!(calls, 1, "one attempt means no retry");
    assert!(sleeper.sleeps.is_empty());

    let mut calls = 0u32;
    let mut sleeper = FakeSleeper::default();
    let _ = jobrunner::run_job(&config(4, 10, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(calls, 4, "the budget caps total attempts including the first");
    assert_eq!(sleeper.sleeps.len(), 3);
}

#[test]
fn delays_grow_monotonic_and_saturate_at_max_delay_ms() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let _ = jobrunner::run_job(&config(6, 50, 400), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(calls, 6);
    let sleeps = &sleeper.sleeps;
    assert_eq!(sleeps.len(), 5);
    for delay in sleeps {
        assert!(*delay >= 1, "a nonzero base delay must produce a wait");
        assert!(*delay <= 400, "delays saturate at max_delay_ms");
    }
    for pair in sleeps.windows(2) {
        assert!(pair[0] <= pair[1], "exponential growth must not shrink");
    }
}

#[test]
fn huge_base_delays_saturate_instead_of_overflowing() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let _ = jobrunner::run_job(&config(4, u64::MAX, 250), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps.len(), 3);
    for delay in &sleeper.sleeps {
        assert_eq!(
            *delay, 250,
            "a base above the cap must saturate at max_delay_ms"
        );
    }
}

#[test]
fn public_api_accepts_a_dyn_sleeper() {
    let mut sleeper = FakeSleeper::default();
    let dyn_sleeper: &mut dyn Sleeper = &mut sleeper;
    let result =
        jobrunner::run_job(&config(2, 5, 50), dyn_sleeper, || {
            Err(RetryError::Transient("once".into()))
        });
    assert!(result.is_err());
}
